import{_ as i,o as l,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Conditional End2end Tracing - Yuval Lifshitz, IBM & Deepika Upadhyay, Clyso GmbH","description":"","frontmatter":{"title":"Conditional End2end Tracing - Yuval Lifshitz, IBM & Deepika Upadhyay, Clyso GmbH","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Conditional Tracing","Lua Scripting","Distributed Storage","System Monitoring"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Conditional_End2end_Tracing_-_Yuval_Lifshitz_IBM_Deepika_Upadhyay_Clyso_GmbH.md","filePath":"posts/2025/Conditional_End2end_Tracing_-_Yuval_Lifshitz_IBM_Deepika_Upadhyay_Clyso_GmbH.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Conditional_End2end_Tracing_-_Yuval_Lifshitz_IBM_Deepika_Upadhyay_Clyso_GmbH.md"};function n(r,a,s,p,_,d){return l(),e("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要-ceph中的条件跟踪与lua脚本应用" tabindex="-1">会议纪要：Ceph中的条件跟踪与Lua脚本应用 <a class="header-anchor" href="#会议纪要-ceph中的条件跟踪与lua脚本应用" aria-label="Permalink to &quot;会议纪要：Ceph中的条件跟踪与Lua脚本应用&quot;">​</a></h3><p><strong>会议主题</strong>: 条件跟踪（Conditional Tracing）在Ceph中的应用，特别是通过Lua脚本实现的多用途上传和慢操作跟踪。</p><p><strong>会议时间</strong>: 不详</p><p><strong>会议地点</strong>: 线上会议</p><p><strong>参会人员</strong>:</p><ul><li>Yal（IBM Red Gateway工程师）</li><li>DEA（SEF工程师，与Klyo合作）</li></ul><h3 id="会议议题" tabindex="-1">会议议题： <a class="header-anchor" href="#会议议题" aria-label="Permalink to &quot;会议议题：&quot;">​</a></h3><ol><li><p><strong>条件跟踪的背景与动机</strong></p><ul><li>跟踪是调试分布式系统中复杂问题（如性能瓶颈、延迟等）的强大工具。</li><li>条件跟踪的优势在于针对特定问题进行跟踪，避免全局跟踪带来的性能开销。</li></ul></li><li><p><strong>条件跟踪的工作原理</strong></p><ul><li>通过RGW（RADOS Gateway）中的Lua脚本，在请求到达时启动条件跟踪。</li><li>用户可以定义哪些操作需要跟踪，例如多部分上传（Multipart Upload）或慢操作（Slow Ops）。</li></ul></li><li><p><strong>演示案例</strong></p><ul><li>通过Lua脚本跟踪多部分上传，帮助调试上传失败的问题。</li><li>当Prometheus监控系统检测到慢操作时，Lua脚本会自动开启跟踪，帮助定位慢操作的原因。</li></ul></li><li><p><strong>架构与部署</strong></p><ul><li>Rook负责管理OSD（对象存储守护进程）和RGW（RADOS网关）的部署、监控和同步。</li><li>跟踪系统基于OpenTelemetry和Jaeger，使用Kubernetes Operator进行部署。</li></ul></li><li><p><strong>未来计划</strong></p><ul><li>迁移到OpenTelemetry的最新架构，支持多站点跟踪。</li><li>增加采样功能，减少跟踪带来的性能开销。</li><li>鼓励开发者为代码添加跟踪支持。</li><li>改进Lua脚本的锁定机制，支持用户级别的脚本，并引入内存和CPU限制。</li></ul></li></ol><h3 id="决定事项与后续行动计划" tabindex="-1">决定事项与后续行动计划： <a class="header-anchor" href="#决定事项与后续行动计划" aria-label="Permalink to &quot;决定事项与后续行动计划：&quot;">​</a></h3><ol><li><strong>跟踪系统的迁移</strong>：计划将当前基于Jaeger的跟踪系统迁移到OpenTelemetry的最新架构。</li><li><strong>采样功能的开发</strong>：增加采样功能，减少跟踪对系统性能的影响。</li><li><strong>Lua脚本的优化</strong>：改进Lua脚本的锁定机制，支持用户级别的脚本，并引入内存和CPU限制。</li><li><strong>开发者社区的推动</strong>：鼓励开发者为代码添加更多的跟踪点，提升系统的可调试性。</li></ol><h3 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h3><p>本次会议详细介绍了Ceph中条件跟踪的概念及其在多部分上传和慢操作中的应用。通过Lua脚本，用户可以灵活地选择需要跟踪的操作，避免全局跟踪带来的性能开销。会议还讨论了未来在跟踪系统和Lua脚本方面的改进计划，旨在提升系统的可调试性和性能。</p>',12)])])}const h=i(o,[["render",n]]);export{g as __pageData,h as default};
